using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    // Technical details: I/O, networking, serialization, persistence.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Text.Json", "System.Data", "System.Diagnostics.Process",
        "Microsoft.Data", "Microsoft.EntityFrameworkCore", "Newtonsoft",
    ];

    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly Infrastructure = typeof(HttpPaymentGateway).Assembly;

    private static void AssertNoViolations(TestResult result, string rule) =>
        Assert.True(result.IsSuccessful,
            $"{rule}. Offending types: {string.Join(", ", result.FailingTypeNames ?? [])}");

    [Fact]
    public void Domain_does_not_depend_on_other_layers() =>
        AssertNoViolations(
            Types.InAssembly(Domain).ShouldNot().HaveDependencyOnAny(ApplicationNs, InfrastructureNs).GetResult(),
            "Domain must not depend on Application or Infrastructure");

    [Fact]
    public void Domain_does_not_use_technical_details() =>
        AssertNoViolations(
            Types.InAssembly(Domain).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces).GetResult(),
            "Domain must not use I/O, network or serialization APIs");

    [Fact]
    public void Application_does_not_depend_on_Infrastructure() =>
        AssertNoViolations(
            Types.InAssembly(Application).ShouldNot().HaveDependencyOn(InfrastructureNs).GetResult(),
            "Application must not depend on Infrastructure");

    [Fact]
    public void Application_does_not_use_technical_details() =>
        AssertNoViolations(
            Types.InAssembly(Application).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces).GetResult(),
            "Application must reach technical details only through its ports");

    [Fact]
    public void Referenced_assemblies_respect_layering()
    {
        static string[] Refs(Assembly a) => a.GetReferencedAssemblies().Select(r => r.Name!).ToArray();
        Assert.DoesNotContain("PaymentAuthorization.Application", Refs(Domain));
        Assert.DoesNotContain("PaymentAuthorization.Infrastructure", Refs(Domain));
        Assert.DoesNotContain("PaymentAuthorization.Infrastructure", Refs(Application));
        Assert.Contains("PaymentAuthorization.Application", Refs(Infrastructure));
    }
}
